288	/** 抽屉挂载完成后查询生产执行详情，供首次打开和页签切回共用。 */
289	function loadProductionDetails() {
290	  const mfgId = detailsMfgId.value;
291	  if (!mfgId) return;
292	
293	  productionDetailsRef.value?.getWorkDetail(mfgId, true);
294	  productionDetailsRef.value?.getProcessXml(mfgId);
