  1	import { computed, onBeforeUnmount, ref } from "vue";
  2	import { throttle } from "lodash-es";
  3	import { findMaterialList } from "@/network/materia";
  4	import { queryBatchLineageLots } from "@/network/batchLineage";
  5	import {
  6	  createLotOptions,
  7	  createMaterialOptions,
  8	  getListData,
  9	} from "./BatchLineageSearch";
 10	import type {
 11	  BatchLineageMaterialOption,
 12	  BatchLineageSearchFormState,
 13	} from "./BatchLineageSearch.types";
 14	
 15	/** 批次血缘图谱的物料与批次联动查询。 */
 16	export function useBatchLineageSearch(formState: BatchLineageSearchFormState) {
 17	  const materialOptions = ref<BatchLineageMaterialOption[]>([]);
 18	  const lotOptions = ref<{ label: string; value: string }[]>([]);
 19	  const selectedMaterialId = ref<number>();
 20	  const selectedMaterialName = ref("");
 21	  let materialRequestId = 0;
 22	  let lotRequestId = 0;
 23	
 24	  const canSearch = computed(
 25	    () => Boolean(selectedMaterialId.value) && Boolean(formState.lot.trim()),
 26	  );
 27	
 28	  const clearMaterial = () => {
 29	    lotRequestId += 1;
 30	    selectedMaterialId.value = undefined;
 31	    selectedMaterialName.value = "";
 32	    formState.lot = null;
 33	    lotOptions.value = [];
 34	  };
 35	
 36	  const fetchMaterials = async (materialName: string, requestId: number) => {
 37	    const res = await findMaterialList({ maName: materialName, onlySearch: 1 });
 38	    if (requestId !== materialRequestId) return;
 39	
 40	    materialOptions.value =
 41	      res?.code === 200 ? createMaterialOptions(getListData(res.data)) : [];
 42	  };
 43	
 44	  // 仅在输入物料名称后触发，500ms 内最多请求一次，并使用最后一次输入的关键词。
 45	  const throttledSearchMaterials = throttle(fetchMaterials, 500, {
 46	    leading: false,
 47	    trailing: true,
 48	  });
 49	
 50	  const searchMaterials = (keyword: string) => {
 51	    const materialName = keyword.trim();
 52	    const requestId = ++materialRequestId;
 53	
 54	    if (!materialName) {
 55	      throttledSearchMaterials.cancel();
 56	      materialOptions.value = [];
 57	      return;
 58	    }
 59	
 60	    throttledSearchMaterials(materialName, requestId);
 61	  };
 62	
 63	  const loadLots = async () => {
 64	    const materialId = selectedMaterialId.value;
 65	    if (!materialId) return;
 66	
 67	    const requestId = ++lotRequestId;
 68	    const res = await queryBatchLineageLots(materialId);
 69	    if (requestId !== lotRequestId || res?.code !== 200) return;
 70	
 71	    lotOptions.value = createLotOptions(getListData(res.data));
 72	  };
 73	
 74	  const handleMaterialChange = (value: string) => {
 75	    if (!value.trim()) {
 76	      searchMaterials("");
 77	    }
 78	
 79	    if (value === selectedMaterialName.value) return false;
 80	    clearMaterial();
 81	    return true;
 82	  };
 83	
 84	  const handleMaterialSelect = async (
 85	    value: string,
 86	    option: BatchLineageMaterialOption,
 87	  ) => {
 88	    throttledSearchMaterials.cancel();
 89	    materialRequestId += 1;
 90	    selectedMaterialName.value = value;
 91	    selectedMaterialId.value = option.maId;
 92	    formState.materialName = value;
 93	    formState.lot = null;
 94	    lotOptions.value = [];
 95	    await loadLots();
 96	  };
 97	
 98	  const setSelectedMaterial = (materialName?: string, maId?: number) => {
 99	    selectedMaterialName.value = materialName || "";
100	    selectedMaterialId.value = maId;
101	  };
102	
103	  const resetSearchOptions = () => {
104	    searchMaterials("");
105	    materialOptions.value = [];
106	    clearMaterial();
107	  };
108	
109	  onBeforeUnmount(() => {
110	    throttledSearchMaterials.cancel();
111	    materialRequestId += 1;
112	  });
113	
114	  return {
115	    canSearch,
116	    handleMaterialChange,
117	    handleMaterialSelect,
118	    loadLots,
119	    lotOptions,
120	    materialOptions,
121	    resetSearchOptions,
122	    searchMaterials,
123	    selectedMaterialId,
124	    setSelectedMaterial,
125	  };
126	}

