 65	  );
 66	  const groupNodeIds = new Map<
 67	    string,
 68	    { parentId: string; direction: BranchDirection; childIds: string[] }
 69	  >();
 70	
 71	  edges.forEach((edge) => {
 72	    const sourceId = String(edge.source);
 73	    const targetId = String(edge.target);
 74	    const sourceNode = nodeMap.get(sourceId);
 75	    const targetNode = nodeMap.get(targetId);
 76	    if (!sourceNode || !targetNode) return;
 77	
 78	    const sourceData = getNodeData(sourceNode);
 79	    const direction =
 80	      sourceData.direction === "upstream" ? "upstream" : "downstream";
 81	    const parentId = direction === "upstream" ? targetId : sourceId;
 82	    const childId = direction === "upstream" ? sourceId : targetId;
 83	    const groupId = `${parentId}:${direction}`;
 84	    const group = groupNodeIds.get(groupId) || {
 85	      parentId,
 86	      direction,
 87	      childIds: [],
 88	    };
 89	
 90	    group.childIds.push(childId);
 91	    groupNodeIds.set(groupId, group);
 92	  });
