100	    return {
101	      id: groupId,
102	      parentId: group.parentId,
103	      direction: group.direction,
104	      childIds: group.childIds,
105	      childX:
106	        childPositions.reduce((total, position) => total + position.x, 0) /
107	        childPositions.length,
108	      firstChildY: Math.min(...childPositions.map((position) => position.y)),
109	      lastChildY: Math.max(...childPositions.map((position) => position.y)),
