194	function getLineageEdges(nodes: NodeData[], lineageEdges: BatchLineageEdge[]) {
195	  const nodeMap = new Map<string, NodeData[]>();
196	  nodes.forEach((node) => {
197	    const nodeKey = getNodeData(node).nodeKey;
198	    if (!nodeKey) return;
199	
200	    const nodeItems = nodeMap.get(nodeKey) || [];
201	    nodeItems.push(node);
202	    nodeMap.set(nodeKey, nodeItems);
203	  });
204	
205	  const getNodeByDirection = (
206	    nodeKey: string,
207	    direction: LineageNodeDirection,
208	  ) =>
209	    nodeMap
210	      .get(nodeKey)
211	      ?.find((node) => getNodeData(node).direction === direction);
212	
213	  return lineageEdges.flatMap((edge, index) => {
214	    // 后端可能返回中心节点指向自身的占位边；该边不属于真实血缘关系，参与布局会产生回环。
215	    if (!edge.fromNodeKey || edge.fromNodeKey === edge.toNodeKey) return [];
216	
217	    const fromNodeKey = edge.fromNodeKey || "";
218	    const toNodeKey = edge.toNodeKey || "";
219	    const fromNodes = {
220	      upstream: getNodeByDirection(fromNodeKey, "upstream"),
221	      center: getNodeByDirection(fromNodeKey, "center"),
222	      downstream: getNodeByDirection(fromNodeKey, "downstream"),
223	    };
224	    const toNodes = {
225	      upstream: getNodeByDirection(toNodeKey, "upstream"),
226	      center: getNodeByDirection(toNodeKey, "center"),
227	      downstream: getNodeByDirection(toNodeKey, "downstream"),
228	    };
229	    const relation = [
230	      [fromNodes.upstream, toNodes.center],
231	      [fromNodes.center, toNodes.downstream],
232	      [fromNodes.upstream, toNodes.upstream],
233	      [fromNodes.downstream, toNodes.downstream],
234	    ].find(([sourceNode, targetNode]) => sourceNode && targetNode);
235	    const [sourceNode, targetNode] = relation || [];
236	    if (!sourceNode || !targetNode) return [];
237	
238	    const direction = getLineageEdgeDirection(sourceNode, targetNode);
239	    return [
240	      {
241	        id: edge.edgeKey || `lineage-edge-${index}`,
242	        source: sourceNode.id,
243	        target: targetNode.id,
244	        style: {
245	          stroke: direction === "upstream" ? "#a8e4df" : "#d7c4f2",
246	          sourcePort: "output",
