427	export function getLayoutNodes(nodes: NodeData[], edges: EdgeData[]) {
428	  const batchNodes = nodes.filter(
429	    (node) => getNodeData(node).kind !== "load-more",
430	  );
431	  const nodeMap = new Map(batchNodes.map((node) => [String(node.id), node]));
432	  const centerNode = batchNodes.find(
433	    (node) => getNodeData(node).direction === "center",
434	  );
435	  if (!centerNode) return nodes;
436	
437	  const centerPosition = getNodePosition(centerNode);
438	  const layers = new Map<string, number>([[String(centerNode.id), 0]]);
439	  const pendingNodeIds = [String(centerNode.id)];
440	
441	  while (pendingNodeIds.length) {
442	    const nodeId = pendingNodeIds.shift() as string;
443	    const layer = layers.get(nodeId) as number;
444	
445	    edges.forEach((edge) => {
446	      const sourceId = String(edge.source);
447	      const targetId = String(edge.target);
448	      const sourceNode = nodeMap.get(sourceId);
449	      const targetNode = nodeMap.get(targetId);
450	      if (!sourceNode || !targetNode) return;
451	
452	      const sourceDirection = getNodeData(sourceNode).direction;
453	      const nextNodeId =
454	        targetId === nodeId && sourceDirection === "upstream"
455	          ? sourceId
456	          : sourceId === nodeId && sourceDirection !== "upstream"
457	            ? targetId
458	            : "";
459	      if (!nextNodeId || layers.has(nextNodeId)) return;
460	
461	      layers.set(nextNodeId, layer + (sourceDirection === "upstream" ? -1 : 1));
462	      pendingNodeIds.push(nextNodeId);
463	    });
464	  }
465	
466	  const layoutNodes = batchNodes.map((node) => ({
467	    ...node,
468	    style: { ...node.style },
469	  }));
470	  const layoutNodeMap = new Map(
471	    layoutNodes.map((node) => [String(node.id), node]),
472	  );
473	  const nodeOrder = new Map<string, number>();
474	
475	  (["upstream", "downstream"] as BranchDirection[]).forEach((direction) => {
476	    const visitedNodeIds = new Set<string>();
477	    const leafNodeIds: string[] = [];
478	
479	    function getChildNodeIds(nodeId: string) {
480	      return edges
481	        .filter((edge) =>
482	          direction === "upstream"
483	            ? String(edge.target) === nodeId
484	            : String(edge.source) === nodeId,
485	        )
486	        .map((edge) =>
487	          direction === "upstream" ? String(edge.source) : String(edge.target),
488	        )
489	        .filter((childNodeId) => nodeMap.has(childNodeId))
490	        .sort(
491	          (firstNodeId, secondNodeId) =>
492	            getNodePosition(nodeMap.get(firstNodeId) as NodeData).y -
493	            getNodePosition(nodeMap.get(secondNodeId) as NodeData).y,
494	        );
495	    }
496	
497	    function walk(nodeId: string): number {
498	      if (visitedNodeIds.has(nodeId)) return nodeOrder.get(nodeId) as number;
499	
500	      visitedNodeIds.add(nodeId);
501	      const childNodeIds = getChildNodeIds(nodeId);
502	      if (!childNodeIds.length) {
503	        const order = leafNodeIds.length;
504	        leafNodeIds.push(nodeId);
505	        nodeOrder.set(nodeId, order);
506	        return order;
507	      }
508	
509	      const childOrders = childNodeIds.map(walk);
510	      const order =
511	        childOrders.reduce((total, childOrder) => total + childOrder, 0) /
512	        childOrders.length;
513	      nodeOrder.set(nodeId, order);
514	      return order;
515	    }
516	
517	    getChildNodeIds(String(centerNode.id)).forEach(walk);
518	    const firstY =
519	      centerPosition.y - ((leafNodeIds.length - 1) * layerNodeGap) / 2;
520	
521	    nodeOrder.forEach((order, nodeId) => {
522	      const node = layoutNodeMap.get(nodeId) as NodeData;
523	      const layer = layers.get(nodeId) as number;
524	
525	      node.style = {
526	        ...node.style,
527	        x: centerPosition.x + layer * layerWidth,
528	        y: firstY + order * layerNodeGap,
529	      };
530	    });
531	  });
532	
533	  const previousGroups = new Map(
534	    nodes
535	      .filter((node) => getNodeData(node).kind === "load-more")
536	      .map((node) => {
537	        const group = getNodeData(node).group as LineageGroupMeta;
538	        return [group.id, group];
539	      }),
540	  );
541	  function getVisibleGroups() {
542	    return getLineageGroups(layoutNodes, edges)
543	      .map((group) => {
544	        const previousGroup = previousGroups.get(group.id);
545	
546	        return previousGroup
547	          ? {
548	              ...group,
549	              displayedCount: previousGroup.displayedCount,
550	              totalCount: previousGroup.totalCount,
551	            }
552	          : group;
553	      })
554	      .filter((group) => group.displayedCount < group.totalCount);
555	  }
556	
557	  function arrangeColumnItems(loadMoreNodes: NodeData[]) {
558	    const columnItems = new Map<number, NodeData[]>();
559	
560	    [...layoutNodes, ...loadMoreNodes].forEach((node) => {
561	      const { x } = getNodePosition(node);
562	      const items = columnItems.get(x) || [];
563	
564	      items.push(node);
565	      columnItems.set(x, items);
566	    });
567	
568	    columnItems.forEach((items) => {
569	      let previousY = Number.NEGATIVE_INFINITY;
570	
571	      items
572	        .sort(
573	          (firstNode, secondNode) =>
574	            getNodePosition(firstNode).y - getNodePosition(secondNode).y,
575	        )
576	        .forEach((node) => {
577	          const position = getNodePosition(node);
578	          const y = Math.max(position.y, previousY + loadMoreOffset);
579	
580	          node.style = { ...node.style, y };
581	          previousY = y;
582	        });
583	
584	      const firstY = getNodePosition(items[0]).y;
585	      const lastY = getNodePosition(items[items.length - 1]).y;
586	      const offsetY = centerPosition.y - (firstY + lastY) / 2;
587	
588	      items.forEach((node) => {
589	        const position = getNodePosition(node);
590	
591	        node.style = { ...node.style, y: position.y + offsetY };
592	      });
593	    });
594	  }
595	
596	  const loadMoreNodes = getVisibleGroups().map(getLoadMoreNode);
597	  arrangeColumnItems(loadMoreNodes);
598	
599	  return [...layoutNodes, ...loadMoreNodes];
600	}
