 79	      { label: "生产工单", value: workOrderInfo || detail?.mfgCode || "--" },
 80	      { label: "生产车间", value: workOrderInfo || detail?.orgName || "--" },
 81	      { label: "当前库存", value: formatQuantity(detail?.stockNum, unit) },
 82	    ],
 83	  };
