/** 将物料接口返回值统一为自动完成组件可用的数据格式。 */
export function createMaterialOptions(data: any[] = []) {
  const materialIds = new Set<number>();

  return data.reduce<BatchLineageMaterialOption[]>((options, item) => {
    const maId = Number(item?.maId ?? item?.materialId);
    const materialName = item?.maName ?? item?.materialName ?? item?.label;
    if (!maId || !materialName || materialIds.has(maId)) return options;

    const maCode = item?.maCode ?? item?.materialCode;
    materialIds.add(maId);
    options.push({
      label: createMaterialLabel(materialName, maCode),
      value: createMaterialLabel(materialName, maCode),
      maId,
      maCode: maCode || undefined,
    });
    return options;
