import {
  createMaterialLabel,
  createMaterialOptions,
} from "../../src/views/batchLineage/BatchLineageSearch";
import {
  getNodeCard,
  getNodeTooltipData,
} from "../../src/views/batchLineage/components/LineageGraph";

/** 1. 物料名称与编码的拼接 */
assert.equal(
  createMaterialLabel("色酚AS-IRG", "GH-1234"),
  "色酚AS-IRG(GH-1234)",
);
assert.equal(createMaterialLabel("色酚AS-IRG"), "色酚AS-IRG");
assert.equal(createMaterialLabel(undefined, "GH-1234"), "(GH-1234)");

/** 2. 搜索候选项：兼容 maCode / materialCode，无编码时只有名称 */
const options = createMaterialOptions([
  { maId: 1, maName: "色酚AS-IRG", maCode: "GH-1234" },
  { maId: 2, maName: "颜料红", materialCode: "GH-2" },
  { maId: 3, maName: "无编码物料" },
  { maId: 1, maName: "重复物料", maCode: "DUP" },
]);
assert.deepEqual(
  options.map((item) => [item.value, item.maId, item.maCode]),
  [
    ["色酚AS-IRG(GH-1234)", 1, "GH-1234"],
    ["颜料红(GH-2)", 2, "GH-2"],
    ["无编码物料", 3, undefined],
  ],
);

/** 3. 血缘节点卡片与悬浮卡片展示物料编码 */
const node = {
  id: "node-1",
  data: {
    direction: "center",
    batchNo: "B001",
    materialName: "色酚AS-IRG",
    materialCode: "GH-1234",
    quantity: "10kg",
    status: "合格",
  },
};

const card = getNodeCard(node as never);
assert.ok(
  card.includes("色酚AS-IRG(GH-1234)"),
  `节点卡片未展示物料编码：${card}`,
);

const tooltip = getNodeTooltipData(node as never);
assert.equal(tooltip.materialCode, "GH-1234");

/** 4. 后端未返回编码时不报错、不留空括号 */
const nodeWithoutCode = {
  id: "node-2",
  data: {
    direction: "upstream",
    batchNo: "B002",
    materialName: "甲醇",
    quantity: "5kg",
    status: "未发起",
  },
};

assert.ok(getNodeCard(nodeWithoutCode as never).includes("甲醇"));
assert.equal(getNodeTooltipData(nodeWithoutCode as never).materialCode, "--");
"}

