 15	/** 批次血缘图谱的物料与批次联动查询。 */
 16	export function useBatchLineageSearch(formState: BatchLineageSearchFormState) {
 17	  const materialOptions = ref<BatchLineageMaterialOption[]>([]);
 18	  const lotOptions = ref<{ label: string; value: string }[]>([]);
 19	  const selectedMaterialId = ref<number>();
 20	  const selectedMaterialName = ref("");
 21	  let materialRequestId = 0;
 22	  let lotRequestId = 0;
 23	
 24	  const canSearch = computed(
 25	    () => Boolean(selectedMaterialId.value) && Boolean(formState.lot.trim()),
 26	  );
 27	
 28	  const clearMaterial = () => {
 29	    lotRequestId += 1;
 30	    selectedMaterialId.value = undefined;
 31	    selectedMaterialName.value = "";
 32	    formState.lot = null;
 33	    lotOptions.value = [];
 34	  };
 35	
 36	  /** 按物料名称或物料编码查询候选物料，候选项同时展示编码。 */
 37	  const fetchMaterials = async (keyword: string, requestId: number) => {
 38	    const res = await findMaterialListByNameOrCode(keyword);
 39	    if (requestId !== materialRequestId) return;
 40	
 41	    materialOptions.value =
 42	      res?.code === 200 ? createMaterialOptions(getListData(res.data)) : [];
 43	  };
 44	
 45	  // 仅在输入物料名称或编码后触发，500ms 内最多请求一次，并使用最后一次输入的关键词。
 46	  const throttledSearchMaterials = throttle(fetchMaterials, 500, {
 47	    leading: false,
 48	    trailing: true,
 49	  });
 50	
 51	  const searchMaterials = (keyword: string) => {
 52	    const materialName = keyword.trim();
 53	    const requestId = ++materialRequestId;
 54	
 55	    if (!materialName) {
 56	      throttledSearchMaterials.cancel();
 57	      materialOptions.value = [];
 58	      return;
 59	    }
 60	
 61	    throttledSearchMaterials(materialName, requestId);
 62	  };
 63	
 64	  const loadLots = async () => {
 65	    const materialId = selectedMaterialId.value;
 66	    if (!materialId) return;
 67	
 68	    const requestId = ++lotRequestId;
 69	    const res = await queryBatchLineageLots(materialId);
 70	    if (requestId !== lotRequestId || res?.code !== 200) return;
 71	
 72	    lotOptions.value = createLotOptions(getListData(res.data));
 73	  };
 74	
 75	  const handleMaterialChange = (value: string) => {
 76	    if (!value.trim()) {
 77	      searchMaterials("");
 78	    }
 79	
 80	    if (value === selectedMaterialName.value) return false;
 81	    clearMaterial();
 82	    return true;
 83	  };
 84	
 85	  const handleMaterialSelect = async (
 86	    value: string,
 87	    option: BatchLineageMaterialOption,
 88	  ) => {
 89	    throttledSearchMaterials.cancel();
 90	    materialRequestId += 1;
 91	    selectedMaterialName.value = value;
 92	    selectedMaterialId.value = option.maId;
 93	    formState.materialName = value;
 94	    formState.lot = null;
 95	    lotOptions.value = [];
 96	    await loadLots();
 97	  };
 98	
 99	  const setSelectedMaterial = (materialName?: string, maId?: number) => {
100	    selectedMaterialName.value = materialName || "";
101	    selectedMaterialId.value = maId;
102	  };
103	
104	  const resetSearchOptions = () => {
105	    searchMaterials("");
106	    materialOptions.value = [];
107	    clearMaterial();
108	  };
109	
110	  onBeforeUnmount(() => {
111	    throttledSearchMaterials.cancel();
112	    materialRequestId += 1;
113	  });
114	
115	  return {
116	    canSearch,
117	    handleMaterialChange,
118	    handleMaterialSelect,
119	    loadLots,
120	    lotOptions,
121	    materialOptions,
122	    resetSearchOptions,
123	    searchMaterials,
124	    selectedMaterialId,
125	    setSelectedMaterial,
126	  };
127	}

