import { computed, onBeforeUnmount, ref } from "vue";
import { throttle } from "lodash-es";
import { findMaterialListByNameOrCode } from "@/network/materia";
import { queryBatchLineageLots } from "@/network/batchLineage";
import {
  createLotOptions,
  createMaterialOptions,
  getListData,
} from "./BatchLineageSearch";
import type {
  BatchLineageMaterialOption,
  BatchLineageSearchFormState,
} from "./BatchLineageSearch.types";

/** 批次血缘图谱的物料与批次联动查询。 */
export function useBatchLineageSearch(formState: BatchLineageSearchFormState) {
  const materialOptions = ref<BatchLineageMaterialOption[]>([]);
  const lotOptions = ref<{ label: string; value: string }[]>([]);
  const selectedMaterialId = ref<number>();
  const selectedMaterialName = ref("");
  let materialRequestId = 0;
  let lotRequestId = 0;

  const canSearch = computed(
    () => Boolean(selectedMaterialId.value) && Boolean(formState.lot.trim()),
  );

  const clearMaterial = () => {
    lotRequestId += 1;
    selectedMaterialId.value = undefined;
    selectedMaterialName.value = "";
    formState.lot = null;
    lotOptions.value = [];
  };

  /** 按物料名称或物料编码查询候选物料，候选项同时展示编码。 */
  const fetchMaterials = async (keyword: string, requestId: number) => {
    const res = await findMaterialListByNameOrCode(keyword);
    if (requestId !== materialRequestId) return;

    materialOptions.value =
      res?.code === 200 ? createMaterialOptions(getListData(res.data)) : [];
  };

  // 仅在输入物料名称或编码后触发，500ms 内最多请求一次，并使用最后一次输入的关键词。
  const throttledSearchMaterials = throttle(fetchMaterials, 500, {
    leading: false,
    trailing: true,
  });

  const searchMaterials = (keyword: string) => {
    const materialName = keyword.trim();
    const requestId = ++materialRequestId;

    if (!materialName) {
      throttledSearchMaterials.cancel();
      materialOptions.value = [];
      return;
    }

    throttledSearchMaterials(materialName, requestId);
  };

  const loadLots = async () => {
    const materialId = selectedMaterialId.value;
    if (!materialId) return;

    const requestId = ++lotRequestId;
    const res = await queryBatchLineageLots(materialId);
    if (requestId !== lotRequestId || res?.code !== 200) return;

    lotOptions.value = createLotOptions(getListData(res.data));
  };

  const handleMaterialChange = (value: string) => {
    if (!value.trim()) {
      searchMaterials("");
    }

    if (value === selectedMaterialName.value) return false;
    clearMaterial();
    return true;
  };

  const handleMaterialSelect = async (
    value: string,
    option: BatchLineageMaterialOption,
  ) => {
    throttledSearchMaterials.cancel();
    materialRequestId += 1;
    selectedMaterialName.value = value;
    selectedMaterialId.value = option.maId;
    formState.materialName = value;
    formState.lot = null;
    lotOptions.value = [];
    await loadLots();
  };

  const setSelectedMaterial = (materialName?: string, maId?: number) => {
    selectedMaterialName.value = materialName || "";
    selectedMaterialId.value = maId;
  };

  const resetSearchOptions = () => {
    searchMaterials("");
    materialOptions.value = [];
    clearMaterial();
  };

  onBeforeUnmount(() => {
    throttledSearchMaterials.cancel();
    materialRequestId += 1;
  });

  return {
    canSearch,
    handleMaterialChange,
    handleMaterialSelect,
    loadLots,
    lotOptions,
    materialOptions,
    resetSearchOptions,
    searchMaterials,
    selectedMaterialId,
    setSelectedMaterial,
